package com.ricozknow.enterprise.health; import com.ricozknow.common.TenantContext; import com.ricozknow.article.ArticleRepository; import com.ricozknow.user.UserRepository; import com.ricozknow.publishing.IndexJobRepository; import com.ricozknow.webhook.WebhookDeliveryRepository; import com.ricozknow.rag.RagApiKeyRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class AdminHealthService {private final ArticleRepository articles; private final UserRepository users; private final IndexJobRepository jobs; private final WebhookDeliveryRepository webhooks; private final RagApiKeyRepository ragKeys; public Map<String,Object> snapshot(){UUID t=TenantContext.get();Map<String,Object> m=new LinkedHashMap<>();m.put("timestamp",Instant.now());m.put("tenantId",t);m.put("users",users.findAll().stream().filter(x->t.equals(x.getTenantId())).count());m.put("articles",articles.findAll().stream().filter(x->t.equals(x.getTenantId())).count());m.put("indexJobs",jobs.findAll().stream().filter(x->t.equals(x.getTenantId())).count());m.put("failedIndexJobs",jobs.findAll().stream().filter(x->t.equals(x.getTenantId())&&x.getStatus()!=null&&x.getStatus().name().equals("FAILED")).count());m.put("webhookFailures",webhooks.findByTenantIdAndStatusOrderByCreatedAtDesc(t, com.ricozknow.webhook.WebhookDelivery.DeliveryStatus.FAILED).size());m.put("ragApiKeys",ragKeys.findByTenantIdOrderByCreatedAtDesc(t).size());m.put("status","UP");return m;}}
